local util = require 'XLua.util'
local CoWait = CS.Engine.Lib.CoWait
---@class ActivityGachaponTowerEntryRoot
local ActivityGachaponTowerEntryRoot = Class("ActivityGachaponTowerEntryRoot")
local KTool = CS.Engine.Lib.KTool
local MinCount = 21
local MaxLayer = 6
local cs_coroutine = require 'XLua.cs_coroutine'
local Yielders = CS.Engine.Lib.Yielders
local ActivityGachaponTowerMgr = import('Game.Activity.GachaponTower.ActivityGachaponTowerMgr')
local UIRaycastBlocker = CS.Engine.UI.UIRaycastBlocker.Instance
--[[local LayTotalCount = {
