}]]


function ActivityGachaponTowerEntryRoot:__init()
    self.itemEnv = {}
    self.curLayer = nil
    self.eventsDecorated_ = CfUtils.EventsDecorated({
        [Constants.EventNames.CommonChooseRewardFinish] = Bind(self, self.RefreshAdd),
    })
end


function ActivityGachaponTowerEntryRoot:RefreshAdd(cellData, index)
    local activityData = ActivityGachaponTowerMgr:GetInstance():GetActivityData(cellData)
    local addData = ActivityGachaponTowerMgr:GetInstance():GetAddData()
    local data = {
        activityUuid = activityData.id,
        rewardId = addData.id,
        location = index
    }

    GameUtils.Request(Interfaces.ActivityMeowSetLuckDrawChooseIds,data,function(request,response)
        if checkNumber(response.errCode) == 0 then
            local tempData = { id = addData.id, index = index}
            ActivityGachaponTowerMgr:GetInstance():ChangeChooseData(tempData)
            self:RefreshAddCell(addData, tempData)
        end
    end)
end

function ActivityGachaponTowerEntryRoot:RefreshAddCell(addData, rewardData)
    if isNotNull(addData) then
        self.itemEnv[addData.layer][addData.index]:RefreshAddShow(rewardData)
    end
end

function ActivityGachaponTowerEntryRoot:__delete()
    CfUtils.EventsUndecorated(self.eventsDecorated_)
    self.controller = nil
    self.itemEnv = nil
    self.curLayer = nil
end

function ActivityGachaponTowerEntryRoot:Awake()

end

function ActivityGachaponTowerEntryRoot:RefreshShow(data, chooseData, ignore)
    local isEnd = ActivityGachaponTowerMgr:GetInstance():IsDrawOver()
    for i, j in pairs(data) do
        local parent = self["RewardRoot"..i]
        local ImgCurrent = self["ImgCurrent"..i]
        if isNotNull(ImgCurrent) and not ignore then
            if isEnd then
                CfUtils.SetActive(ImgCurrent.gameObject,false)
            else
                CfUtils.SetActive(ImgCurrent.gameObject,self.curLayer == i)
            end
        end

        if not isNull(parent) then
            for k, v in pairs(j) do
                if isNull(self.itemEnv[i]) then
                    self.itemEnv[i] = {}
                end
                v.index = k
                local isShow = self:IsShowSpecialEffect(i)
                if isNull(self.itemEnv[i][k]) then
                    local go = CS.UnityEngine.GameObject.Instantiate(self.Node.gameObject)
                    KTool.SetParent(go,parent.gameObject,false)
                    local env = CfUtils.GetLuaScr(go,"Game.Activity.GachaponTower.Cell.ActivityGachaponTowerEntryRewardNode")
                    if not isNull(env) then
                        env:RefreshShow(v , chooseData, isShow)
                        self.itemEnv[i][k] = env
                    end
                else
                    self.itemEnv[i][k]:RefreshShow(v,chooseData, isShow)
                end
            end
        end
    end
end

function ActivityGachaponTowerEntryRoot:SetCurLayer(layer)
    self.curLayer = layer
end

---是否显示特殊道具光效
---层数为第6层 并且当前层不是第6层则显示
function ActivityGachaponTowerEntryRoot:IsShowSpecialEffect(layer)
    if layer == MaxLayer and not (self.curLayer == MaxLayer) then
        return true
    end

    return false
end

function ActivityGachaponTowerEntryRoot:RefreshLayerShow(layer)
    local lastLayer = self.curLayer
    if not isNull(lastLayer) then
        local layerItem = self["ImgCurrent"..lastLayer]
        CfUtils.PlayAnimation(layerItem,"ActivityGachaponTowerEntryDialog_ImgCurrent_Out")
        --CfUtils.SetActive(layerItem,false)
    end

    self.curLayer = layer
    if isNotNull(self.curLayer) then
        local layerItem = self["ImgCurrent"..self.curLayer]
        CfUtils.SetActive(layerItem,true)
        CfUtils.PlayAnimation(layerItem,"ActivityGachaponTowerEntryDialog_ImgCurrent_Entry")
    end

    if self.curLayer == MaxLayer then
        for i, v in pairs(self.itemEnv[self.curLayer]) do
            v:SetSpecialEffectActive(false)
        end
    end
end

function ActivityGachaponTowerEntryRoot:StartAnimation(rewardIndex, layer, startCallBack, endCallBack)
    --self.curLayer = layer
    --local MinCount = LayTotalCount[self.curLayer]
    UIRaycastBlocker:AddCondition("ActivityGachaponTowerEntryRoot_Anim")
    local itemCount = table.count(self.itemEnv[self.curLayer])
    local index = MinCount % itemCount
    if index == 0 then
        index = itemCount
    end
    local totalCount = MinCount
    if rewardIndex <= index then
        totalCount = totalCount + (itemCount - index) + rewardIndex
    else
        totalCount = totalCount + rewardIndex - index
    end

    self.curEffectIndex = nil
    self:RemoveAniCo()
    self.startAniCo = cs_coroutine.start(function()
        for i = 1, totalCount do
            local index = i % itemCount
            if index == 0 then
                index = itemCount
            end
            local lastIndex = self.curEffectIndex
            if isNotNull(lastIndex) then
                local time = self:GetDurationTime(i)
                cs_coroutine.yield_return(Yielders.GetWaitForSeconds(time))
                local Node = self.itemEnv[self.curLayer][lastIndex]
                if isNotNull(Node) then
                    Node:SetEffectActive(false)
                end
            end
            self.curEffectIndex = index
            local Node = self.itemEnv[self.curLayer][self.curEffectIndex]
            if isNotNull(Node) then
                Node:SetEffectActive(true)
            end
        end

        local Node = self.itemEnv[self.curLayer][rewardIndex]
        if isNotNull(Node) then
            Node:SetFinishEffectActive(true)
            cs_coroutine.yield_return(Yielders.GetWaitForSeconds(0.5))
            Node:InitNodeEffect()
        end

        if isNotNull(endCallBack) then
            endCallBack()
        end

        UIRaycastBlocker:RemoveCondition("ActivityGachaponTowerEntryRoot_Anim")
    end)
end

function ActivityGachaponTowerEntryRoot:RemoveAniCo()
    if isNotNull(self.startAniCo) then
        cs_coroutine.stop(self.startAniCo)
        self.startAniCo = nil
    end
end

function ActivityGachaponTowerEntryRoot:GetDurationTime(count)
    if count > 0 and count <= 3 then
        return 0.15
    elseif count > 3 and count <= 18 then
        return 0.06
    else
        return 0.3
    end
end

function ActivityGachaponTowerEntryRoot:OnDestroy()
    self:RemoveAniCo()
    self.controller = nil --删除lua层引⽤到的c#对象否则不会产⽣c# gc回收到对象
    self:Delete()
end

return ActivityGachaponTowerEntryRoot